    const signedMatch = block.match(/^signed:\s*(.+)$/im);
    meetings.push({
      transaction_id: match[1],
      owner: ownerMatch ? ownerMatch[1].trim() : "",
      signed: signedMatch ? signedMatch[1].trim().toLowerCase() === "true" : false,
    });
  }
  return meetings;
}

